package it.trentosmartmountain.app.ui.screens.registraimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Groupsimport androidx.compose.material.icons.filled.Warningimport androidx.compose.material3.FloatingActionButtonimport androidx.compose.material3.Iconimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.res.stringResourceimport androidx.compose.ui.unit.dpimport it.trentosmartmountain.app.Rimport it.trentosmartmountain.app.ui.theme.TsmColorsimport it.trentosmartmountain.app.ui.theme.TsmPrimaryimport it.trentosmartmountain.app.ui.theme.TsmSos/** * Barra inferiore: partecipanti (sinistra), controlli centrali (REC / play-stop), * SOS (destra) — allineati sulla stessa riga. */@Composablefun RegistraBottomControlsBar(  showParticipants: Boolean,  onParticipantsClick: () -> Unit,  showSos: Boolean,  onSosClick: () -> Unit,  centerContent: @Composable () -> Unit,  modifier: Modifier = Modifier,) {  Box(    modifier =      modifier        .fillMaxWidth()        .padding(horizontal = RegistraLayout.bottomBarHorizontalPadding),  ) {    if (showParticipants) {      FloatingActionButton(        onClick = onParticipantsClick,        modifier =          Modifier            .align(Alignment.CenterStart)            .size(RegistraLayout.primaryFabSize),        containerColor = TsmColors.AlpinePineDark,        contentColor = Color.White,      ) {        Icon(          imageVector = Icons.Filled.Groups,          contentDescription = stringResource(R.string.group_roster_cd),          modifier = Modifier.size(RegistraLayout.primaryFabIconSize),        )      }    }    Box(modifier = Modifier.align(Alignment.Center)) {      centerContent()    }    if (showSos) {      RegistraGlowFab(        onClick = onSosClick,        icon = Icons.Filled.Warning,        contentDescription = stringResource(R.string.registra_sos_cd),        modifier = Modifier.align(Alignment.CenterEnd),        fabSize = RegistraLayout.primaryFabSize,        iconSize = RegistraLayout.primaryFabIconSize,        containerColor = TsmPrimary,        glowColor = TsmPrimary,        showGlow = false,      )    }  }}